/**
 * Nord Electro 6 (`.ne6p`) body reader — read-only, firmware-derived.
 *
 * Applies the Electro 6 OS 2.66 registry layout (`layout.generated.ts`,
 * generated by scripts/gen-fw-program-maps.py) through the shared block-chain
 * reader (clavia/block-chain.ts):
 *
 * | Body | Block (payload bytes)          | Body | Block (payload bytes)        |
 * |------|--------------------------------|------|------------------------------|
 * | 0    | u32 format version (2.00-2.04) | 123  | OrgMan Comm (9)              |
 * | 4    | MultiComm (14)                 | 133  | OrgMan A: PresetComm (8)     |
 * | 19   | Piano (17)                     | 142  | OrgMan A: Preset I (14)      |
 * | 37   | Synth (23)                     | 157  | OrgMan A: Preset II (14)     |
 * | 61   | Effects (31)                   | 172  | OrgMan B: PresetComm (8)     |
 * | 93   | Organ (9)                      | 181  | OrgMan B: Preset I (14)      |
 * | 103  | OrganMultiA (9)                | 196  | OrgMan B: Preset II (14)     |
 * | 113  | OrganMultiB (9)                |      | (chain ends at 211)          |
 *
 * The version word and the length-prefixed chain must end exactly at EOF;
 * anything else returns the header-only result with a warning. Never throws.
 */
import { decodeFwProgram } from '../clavia/block-chain';
import { NE6_LAYOUT } from './layout.generated';
import type { Ne6Program } from './types';

export function decodeNe6(bytes: Uint8Array): Ne6Program {
  return { format: 'ne6p', ...decodeFwProgram(bytes, NE6_LAYOUT) };
}
